package com.example.disputeportal.entity;

import java.time.Duration;
import java.time.LocalDateTime;
import java.util.Arrays;
import java.util.Set;
import java.util.TreeSet;
import java.util.stream.Collectors;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

@Entity
@Table(name = "api_clients")
public class ApiClient {

    /**
     * Primary key, generated by the database (an identity column).
     */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /**
     * Human-readable client name, e.g. transaction-loader. Shown in logs.
     * Unique.
     */
    @Column(nullable = false, unique = true, length = 50)
    private String name;

    /**
     * SHA-256 of the API key, as 64 hex characters. The key itself is never
     * stored, so a database leak doesn't expose usable keys.
     */
    @Column(name = "key_hash", nullable = false, unique = true, length = 64)
    private String keyHash;

    /**
     * Set to false to switch a client off without deleting it.
     */
    @Column(nullable = false)
    private boolean enabled;

    /**
     * When the client was registered.
     */
    @Column(name = "created_at", nullable = false, updatable = false)
    private LocalDateTime createdAt;

    /**
     * When the key was last used, updated at most every few minutes. Handy for
     * spotting unused or stolen keys.
     */
    @Column(name = "last_used_at")
    private LocalDateTime lastUsedAt;

    /**
     * Optional expiry. After this time the key stops working.
     */
    @Column(name = "expires_at")
    private LocalDateTime expiresAt;

    /**
     * What this client is allowed to do, as comma-separated scope names such as
     * "transactions:load" (see
     * {@link com.example.disputeportal.security.ApiScopes}). Each key gets only
     * the scopes it needs.
     */
    @Column(nullable = false, length = 200)
    private String scopes;

    protected ApiClient() {
        // required by JPA
    }

    /**
     * Creates an enabled client with the given key hash and permissions.
     *
     * @param scopes comma-separated scope names, e.g. "transactions:load"
     */
    public ApiClient(String name, String keyHash, String scopes, LocalDateTime createdAt) {
        this.name = name;
        this.keyHash = keyHash;
        this.scopes = scopes;
        this.createdAt = createdAt;
        this.enabled = true;
    }

    /**
     * A client may authenticate only while it is enabled and not expired.
     */
    public boolean isUsableAt(LocalDateTime now) {
        return enabled && (expiresAt == null || expiresAt.isAfter(now));
    }

    /**
     * Records use, at most once per interval, so a busy client doesn't cause a
     * write per request.
     */
    public void markUsed(LocalDateTime now, Duration minInterval) {
        if (lastUsedAt == null || lastUsedAt.plus(minInterval).isBefore(now)) {
            lastUsedAt = now;
        }
    }

    /**
     * Rotation: from now on only the new key works and the old one is rejected.
     */
    public void replaceKeyHash(String newKeyHash) {
        this.keyHash = newKeyHash;
    }

    /**
     * Changes what the client may do (the configuration is the source of truth,
     * so this follows it).
     */
    public void replaceScopes(String newScopes) {
        this.scopes = newScopes;
    }

    /**
     * The scopes as a set (an empty set if none are stored).
     */
    public Set<String> getScopes() {
        return Arrays.stream(scopes.split(","))
                .map(String::trim)
                .filter(s -> !s.isEmpty())
                .collect(Collectors.toCollection(TreeSet::new));
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getKeyHash() {
        return keyHash;
    }

    public boolean isEnabled() {
        return enabled;
    }

    public LocalDateTime getLastUsedAt() {
        return lastUsedAt;
    }
}
